tasks_data = data_rows('Tasks', {'K': 'string', 'L': 'number'}, 419, 425)
durations = {cell('Tasks', f'K{r}'): num('Tasks', f'L{r}') for r in tasks_data}
deps_data = data_rows('Dependencies', {'K': 'string', 'L': 'string'}, 37, 43)
deps = {}
for r in deps_data:
    succ = cell('Dependencies', f'K{r}')
    pred = cell('Dependencies', f'L{r}')
    deps.setdefault(succ, []).append(pred)

memo = {}
def get_completion(task):
    if task in memo:
        return memo[task]
    duration = durations[task]
    predecessors = deps.get(task, [])
    if not predecessors:
        start = 0
    else:
        start = max(get_completion(p) for p in predecessors)
    completion = start + duration
    memo[task] = completion
    return completion

result = int(max(get_completion(t) for t in durations))

