tasks = dict(zip(values('Tasks', 'K420:K425'), values('Tasks', 'L420:L425')))
deps = list(zip(values('Dependencies', 'K38:K43'), values('Dependencies', 'L38:L43')))

succ = {}
pred = {t: [] for t in tasks}
for s, p in deps:
    succ.setdefault(p, []).append(s)
    pred[s].append(p)

# Forward pass (earliest start/finish)
es = {}
ef = {}
# Topological order using simple in-degree
indeg = {t: len(pred[t]) for t in tasks}
queue = [t for t in tasks if indeg[t] == 0]
while queue:
    curr = queue.pop(0)
    start = max([ef[p] for p in pred[curr]], default=0)
    es[curr] = start
    ef[curr] = start + tasks[curr]
    for s in succ.get(curr, []):
        indeg[s] -= 1
        if indeg[s] == 0:
            queue.append(s)

project_duration = max(ef.values())

# Backward pass (latest start/finish)
ls = {}
lf = {}
for t in tasks:
    lf[t] = project_duration

# Reverse topological order
queue = [t for t in tasks if not succ.get(t)]
# We can compute using reverse dependency
rev_succ = {t: [] for t in tasks}
for s, p in deps:
    rev_succ[s].append(p)

outdeg = {t: len(succ.get(t, [])) for t in tasks}
queue = [t for t in tasks if outdeg[t] == 0]
while queue:
    curr = queue.pop(0)
    finish = min([ls[s] for s in succ.get(curr, [])], default=project_duration)
    lf[curr] = finish
    ls[curr] = finish - tasks[curr]
    for p in pred[curr]:
        outdeg[p] -= 1
        if outdeg[p] == 0:
            queue.append(p)

# Total slack of Permit = latest start - earliest start
target = 'Permit'
result = int(ls[target] - es[target])

